"""Reading records."""


class Reading:
    def __init__(self, sensor, level):
        self.sensor = sensor
        self.level = level

    def __repr__(self):
        return "Reading(%r, %r)" % (self.sensor, self.level)


ROWS = [('west', 24), ('south', 55), ('north', 43), ('north', 38), ('west', 15), ('south', 45), ('south', 26)]


def load_readings():
    """Yield the stored readings one at a time."""
    for sensor, level in ROWS:
        yield Reading(sensor, level)

