"""Registry of readings by sensor."""

_ALL = []
_BY_KEY = None


def reset():
    """Forget every registered reading."""
    global _BY_KEY
    del _ALL[:]
    _BY_KEY = None


def register(reading):
    """Add one reading to the registry."""
    _ALL.append(reading)


def find(sensor):
    """Return the readings registered under this sensor."""
    global _BY_KEY
    if _BY_KEY is None:
        _BY_KEY = {}
        for x in _ALL:
            _BY_KEY.setdefault(x.sensor, []).append(x)
    return _BY_KEY.get(sensor, [])


def sensor_names(readings):
    """Return the distinct sensor values, in first-seen order."""
    names = []
    for x in readings:
        if x.sensor not in names:
            names.append(x.sensor)
    return names


def describe_reading(reading):
    """Return a one-line description of a reading."""
    return "%s: %s" % (reading.sensor, reading.level)

